import React from "react";

import Layout from "./Layout";
import noticeTemplate from "../ppm/config/notice--template";
import NoticePage from "../ppm/modules/notice/NoticePage";
import type { NoticeAction } from "../ppm/modules/notice/NoticePage";

const actions: NoticeAction[] = [
  { label: "View Properties", to: "/properties", variant: "gold" },
  { label: "Return Home", to: "/", variant: "outline" },
];

/**
 * Page Not Found — for an address that does not lead anywhere.
 *
 * The counterpart to TemporaryPage, and deliberately a different message: this
 * one says the address is wrong, where that one says the feature is not ready.
 * Confusing the two would tell a visitor to wait for a page that is never
 * coming, or tell them a real feature is broken.
 *
 * Shared by both fallbacks so a visitor sees the same page either way: the
 * catch-all route at pages/[...] handles navigation inside the site, while
 * Gatsby builds pages/404 into the 404.html that a host serves on a cold hit.
 *
 * The copy stays in plain English. A visitor who mistyped an address does not
 * need to hear about routes, builds or the number 404 twice over — the figure
 * is there as the outlined word because it is the one thing people recognise.
 */
export default function NotFoundPage() {
  return (
    <Layout>
      <NoticePage
        template={noticeTemplate}
        backgroundText="404"
        title="Page Not Found"
        description={
          "We could not find the page you were looking for. The address may " +
          "be mistyped, or the page may have moved."
        }
        actions={actions}
      />
    </Layout>
  );
}
