import React from "react";
import type { HeadFC, PageProps } from "gatsby";

import Layout from "../components/Layout";
import NotFoundPage from "../components/NotFoundPage";
import Seo from "../components/Seo";
import { featuredImage, isPublished } from "../ppm/modules/property/derive";
import { propertySlug } from "../ppm/modules/property/catalogueRules";
import type { PropertyRecord } from "../ppm/modules/property/types";
import { resolveProperty } from "../ppm/primitives/property/property-images";
import { useCatalogue } from "../ppm/primitives/property/useCatalogue";
import { ListingDetail } from "../sajra/Detail";
import { priceLabel } from "../sajra/Listings";

type Context = { slug?: string; property?: PropertyRecord };

/**
 * One listing page. Built at deploy time for every published property, and
 * also resolvable in the browser by slug, so a listing published in the CMS
 * works before the next deploy has built its static page.
 */
export default function PropertyPage({ pageContext, location }: PageProps<object, Context>) {
  const { data, ready, error } = useCatalogue();
  const slug = propertySlug(location.pathname) ?? pageContext.slug;
  const record = data.find((item) => item.slug === slug);

  if (!record || !isPublished(record)) {
    if (!ready || error) {
      return (
        <Layout>
          <p role="status" style={{ padding: "4rem 1.5rem", textAlign: "center" }}>
            {error ? "Listing details are temporarily unavailable. Please try again shortly." : "Loading listing…"}
          </p>
        </Layout>
      );
    }
    return <NotFoundPage />;
  }

  return (
    <Layout>
      <ListingDetail property={resolveProperty(record)} />
    </Layout>
  );
}

export const Head: HeadFC<object, Context> = ({ pageContext, location }) => {
  const { data } = useCatalogue();
  const slug = propertySlug(location.pathname) ?? pageContext.slug;
  const record = data.find((item) => item.slug === slug);

  if (!record || !isPublished(record)) {
    return (
      <>
        <title>Listing | Sold by Sajra</title>
        <meta name="robots" content="noindex, follow" />
      </>
    );
  }

  const property = resolveProperty(record);
  const photo = featuredImage(record)?.src || property.image || undefined;

  return (
    <Seo
      title={`${property.title} | Sold by Sajra`}
      description={
        property.summary ||
        `${property.type} in ${property.location}, listed at ${priceLabel(property)} by Sajra Ibrahimagic.`
      }
      pathname={`/properties/${property.slug}/`}
      image={photo}
      type="article"
    />
  );
};
