import React from "react";

import type { SectionTitleTemplate } from "../../templates/section-title/default-template";
import useInView from "../shared/useInView";

export type SectionTitleAlign = "left" | "center" | "right";
export type SectionTitleVariant = "default" | "inline";

export type SectionTitleProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: SectionTitleTemplate;
  /** The oversized outlined word behind the heading. Omit to render none. */
  backgroundText?: string;
  title: string;
  description?: string;
  align?: SectionTitleAlign;
  variant?: SectionTitleVariant;
  /** Heading level, so pages keep a sensible document outline. */
  as?: "h1" | "h2" | "h3";
  className?: string;
  id?: string;
};

/**
 * The site-wide section heading.
 *
 * Built once and reused everywhere — Featured Properties, Why Choose Us,
 * Property Details, Search Results and the rest. Sections pass content; they
 * never rebuild the treatment.
 */
export default function SectionTitle({
  template,
  backgroundText,
  title,
  description,
  align = "left",
  variant = "default",
  as: Heading = "h2",
  className,
  id,
}: SectionTitleProps) {
  const { ref, inView } = useInView<HTMLDivElement>();

  const root = template.rootClass;
  const classes = [
    root,
    `${root}--${align}`,
    `${root}--${variant}`,
    inView ? `${root}--in` : "",
    className || "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div
      className={classes}
      ref={ref}
      id={id}
      /* Character count drives the ghost's fit-to-width calc in CSS. Spaces
         are counted too: they are narrower than the estimate, which only makes
         the result safer. */
      style={
        backgroundText
          ? ({ ["--kr-ghost-chars"]: String(backgroundText.length) } as React.CSSProperties)
          : undefined
      }
    >
      {backgroundText ? (
        <div className={`${root}__ghost-wrap`} aria-hidden="true">
          {/* Decorative only — hidden from assistive technology so the word is
              not announced twice alongside the real heading. */}
          <span className={`${root}__ghost`}>{backgroundText}</span>
        </div>
      ) : null}

      <div className={`${root}__content`}>
        <Heading className={`${root}__title`}>{title}</Heading>

        {variant === "inline" ? (
          description ? (
            <span className={`${root}__divider`} aria-hidden="true" />
          ) : null
        ) : (
          <span className={`${root}__rule`} aria-hidden="true" />
        )}

        {description ? (
          <p className={`${root}__description`}>{description}</p>
        ) : null}
      </div>
    </div>
  );
}
