import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Link } from "gatsby";
import {
  LuBath,
  LuBedDouble,
  LuCalendar,
  LuCheck,
  LuChevronLeft,
  LuChevronRight,
  LuHouse,
  LuImages,
  LuMapPin,
  LuPhone,
  LuRuler,
  LuX,
} from "react-icons/lu";

import { AGENT_NAME, BROKERAGE } from "../ppm/config/profile--business-name";
import { PHONE_DISPLAY, PHONE_HREF } from "../ppm/config/profile--contact";
import { availabilityOf, galleryCategories } from "../ppm/modules/property/derive";
import type { GalleryImage } from "../ppm/modules/gallery/types";
import type { Property } from "../ppm/modules/property/types";
import { PORTRAIT } from "./content";
import InquiryForm from "./InquiryForm";
import { ListingGrid, isSample, num, priceLabel, priceOf, useListings } from "./Listings";

function Lightbox({ images, start, onClose }: { images: GalleryImage[]; start: number; onClose: () => void }) {
  const [i, setI] = useState(start);
  const step = useCallback((d: number) => setI((v) => (v + d + images.length) % images.length), [images.length]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowRight") step(1);
      if (e.key === "ArrowLeft") step(-1);
    };
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener("keydown", onKey);
    };
  }, [onClose, step]);

  const image = images[i];
  return (
    <div className="sbs-lightbox" role="dialog" aria-modal="true" aria-label="Photo gallery" onClick={onClose}>
      <button type="button" className="sbs-lightbox__close" onClick={onClose} aria-label="Close gallery">
        <LuX size={26} />
      </button>
      <button type="button" className="sbs-lightbox__nav sbs-lightbox__nav--prev" onClick={(e) => (e.stopPropagation(), step(-1))} aria-label="Previous photo">
        <LuChevronLeft size={30} />
      </button>
      <figure onClick={(e) => e.stopPropagation()}>
        <img src={image.src} alt={image.alt} />
        <figcaption>
          {image.label} · {i + 1} / {images.length}
        </figcaption>
      </figure>
      <button type="button" className="sbs-lightbox__nav sbs-lightbox__nav--next" onClick={(e) => (e.stopPropagation(), step(1))} aria-label="Next photo">
        <LuChevronRight size={30} />
      </button>
    </div>
  );
}

const fmtDate = (iso?: string) =>
  iso ? new Date(`${iso}T12:00:00`).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }) : null;

/** One listing: hero, facts, gallery with lightbox, description, details and an enquiry panel. */
export function ListingDetail({ property }: { property: Property }) {
  const all = useListings();
  const images: GalleryImage[] = useMemo(
    () =>
      property.images?.length
        ? property.images
        : [{ id: "main", src: property.image, srcSet: property.imageSrcSet, alt: property.imageAlt, label: "Photo" }],
    [property]
  );
  const categories = galleryCategories(images);
  const [tab, setTab] = useState("All");
  const [open, setOpen] = useState<number | null>(null);
  const visible = tab === "All" ? images : images.filter((img) => img.category === tab);

  const price = priceOf(property);
  const state = availabilityOf(property);
  const similar = all.filter((p) => p.slug !== property.slug).slice(0, 3);
  const paragraphs = property.content?.paragraphs?.length ? property.content.paragraphs : property.summary ? [property.summary] : [];
  const hero = images[0];

  const details: [string, string][] = [
    ["List price", priceLabel(property)],
    ...(price && property.area ? [["Price per sq ft", `$${num.format(Math.round(price / property.area))}`] as [string, string]] : []),
    ["Home type", property.type],
    ["Bedrooms", String(property.bedrooms)],
    ["Bathrooms", String(property.bathrooms)],
    ["Interior size", `${num.format(property.area)} sq ft`],
    ["Status", property.availability ?? "Contact for status"],
    ...(property.listedOn ? [["Listed", fmtDate(property.listedOn) ?? ""] as [string, string]] : []),
    ["Location", property.location],
  ];

  return (
    <>
      <section className="sbs-dhero">
        {hero?.src ? <img src={hero.src} srcSet={hero.srcSet} alt={hero.alt} /> : null}
        <div className="sbs-dhero__shade" />
        <div className="sbs-wrap sbs-dhero__inner">
          <Link to="/properties/" className="sbs-dhero__back">
            ← All listings
          </Link>
          <div className="sbs-dhero__row">
            <div>
              <div className="sbs-dhero__chips">
                {property.availability ? <span className={`sbs-chip${state === "available" ? " sbs-chip--gold" : ""}`}>{property.availability}</span> : null}
                {isSample(property) ? <span className="sbs-chip sbs-chip--sample">Sample listing</span> : null}
              </div>
              <h1 className="sbs-title">{property.content?.title || property.title}</h1>
              <p className="sbs-dhero__loc">
                <LuMapPin size={17} aria-hidden="true" /> {property.location}
              </p>
            </div>
            <div className="sbs-dhero__aside">
              <p className="sbs-dhero__price">{priceLabel(property)}</p>
              {images.length > 1 ? (
                <button type="button" className="sbs-btn sbs-btn--gold" onClick={() => setOpen(0)}>
                  <LuImages size={17} /> View all {images.length} photos
                </button>
              ) : null}
            </div>
          </div>
        </div>
      </section>

      <section className="sbs-factbar" aria-label="Key facts">
        <div className="sbs-wrap sbs-factbar__grid">
          <div>
            <LuBedDouble size={22} aria-hidden="true" />
            <b>{property.bedrooms}</b>
            <span>Bedrooms</span>
          </div>
          <div>
            <LuBath size={22} aria-hidden="true" />
            <b>{property.bathrooms}</b>
            <span>Bathrooms</span>
          </div>
          <div>
            <LuRuler size={22} aria-hidden="true" />
            <b>{num.format(property.area)}</b>
            <span>Square feet</span>
          </div>
          <div>
            <LuHouse size={22} aria-hidden="true" />
            <b>{property.type}</b>
            <span>Home type</span>
          </div>
          <div>
            <LuCalendar size={22} aria-hidden="true" />
            <b>{property.listedOn ? new Date(`${property.listedOn}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "—"}</b>
            <span>Listed</span>
          </div>
        </div>
      </section>

      <section className="sbs-section" style={{ paddingTop: 56 }}>
        <div className="sbs-wrap sbs-detail">
          <div>
            {images.length > 1 ? (
              <div id="photos">
                <div className="sbs-gtabs" role="tablist" aria-label="Photo categories">
                  {["All", ...categories].map((name) => (
                    <button key={name} type="button" role="tab" aria-selected={tab === name} className={tab === name ? "is-on" : undefined} onClick={() => setTab(name)}>
                      {name}
                    </button>
                  ))}
                </div>
                <div className="sbs-gallery">
                  {visible.map((img) => (
                    <button key={img.id} type="button" onClick={() => setOpen(images.indexOf(img))} aria-label={`Open photo: ${img.label}`}>
                      <img src={img.src} srcSet={img.srcSet} alt={img.alt} loading="lazy" />
                      <span>{img.label}</span>
                    </button>
                  ))}
                </div>
              </div>
            ) : null}

            <div className="sbs-prose" style={{ marginTop: images.length > 1 ? 64 : 0 }}>
              <span className="sbs-eyebrow">About this home</span>
              {property.content?.lead ? <h2 className="sbs-title sbs-title--md">{property.content.lead}</h2> : null}
              <div style={{ marginTop: 22 }}>
                {paragraphs.map((text) => (
                  <p key={text}>{text}</p>
                ))}
              </div>
            </div>

            {property.amenities?.length ? (
              <div style={{ marginTop: 56 }}>
                <span className="sbs-eyebrow">Features</span>
                <ul className="sbs-amen">
                  {property.amenities.map((item) => (
                    <li key={item}>
                      <LuCheck size={16} aria-hidden="true" /> {item}
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}

            <div style={{ marginTop: 56 }}>
              <span className="sbs-eyebrow">Details</span>
              <dl className="sbs-dl">
                {details.map(([k, v]) => (
                  <div key={k}>
                    <dt>{k}</dt>
                    <dd>{v}</dd>
                  </div>
                ))}
              </dl>
            </div>
          </div>

          <aside className="sbs-side">
            <p className="sbs-price" style={{ fontSize: "2.2rem" }}>
              {priceLabel(property)}
            </p>
            <p className="sbs-listing__loc" style={{ marginTop: 0 }}>
              {property.availability ?? "Contact for status"}
            </p>
            <div className="sbs-agent">
              <img src={PORTRAIT} alt={AGENT_NAME} />
              <div>
                <b>{AGENT_NAME}</b>
                <span>REALTOR® · {BROKERAGE}</span>
              </div>
            </div>
            <h2 className="sbs-card-title" style={{ margin: "26px 0 18px" }}>
              Ask about this home
            </h2>
            <InquiryForm subject={`Listing enquiry: ${property.title} (${property.location})`} />
            <a href={PHONE_HREF} className="sbs-side__call">
              <LuPhone size={16} aria-hidden="true" /> Or call {PHONE_DISPLAY}
            </a>
          </aside>
        </div>
      </section>

      {similar.length ? (
        <section className="sbs-section sbs-alt">
          <div className="sbs-wrap">
            <span className="sbs-eyebrow">Keep looking</span>
            <h2 className="sbs-title sbs-title--md">More homes you may like</h2>
            <ListingGrid listings={similar} />
          </div>
        </section>
      ) : null}

      {open !== null ? <Lightbox images={images} start={open} onClose={() => setOpen(null)} /> : null}
    </>
  );
}
